// =========================================================
// RULE-31 | AD-LAPS-GMSA-SensitiveAttribute-Read
// Description : Detects unauthorized reads of LAPS local
//               admin passwords (ms-Mcs-AdmPwd / 4662) and
//               Group Managed Service Account passwords
//               (msDS-ManagedPassword / 4662). Attackers
//               use LAPSToolkit and GMSAPasswordReader to
//               harvest these credentials for lateral
//               movement without touching LSASS.
// Severity    : High
// Tactic      : CredentialAccess (T1552.004, T1555)
// Tables      : SecurityEvent
// Frequency   : PT15M / PT15M
// Suppress    : PT4H
// =========================================================

let LookbackPeriod  = 15m;

// Privileged accounts with legitimate LAPS/GMSA read access
// (Adjust per environment — accounts like SCCM clients, Intune,
//  monitoring tools are expected to read LAPS)
let LegitimateReaders = dynamic([
    "sccm-client", "intune", "laps-service",
    "azureaddevicesync", "msol_", "adsync"
]);

// Sensitive attribute GUIDs
// ms-Mcs-AdmPwd        : {43F8B798-..} — LAPS plaintext password
// ms-Mcs-AdmPwdExpirationTime : LAPS expiry
// msDS-ManagedPassword : GMSA password blob
// msDS-ManagedPasswordId: GMSA key ID
// msDS-ManagedPasswordInterval: GMSA rotation interval
let SensitiveAttrGUIDs = dynamic([
    "ms-Mcs-AdmPwd",
    "ms-Mcs-AdmPwdExpirationTime",
    "msDS-ManagedPassword",
    "msDS-ManagedPasswordId",
    "msDS-ManagedPasswordInterval"
]);

// EventID 4662: An operation was performed on an object
// ObjectType = attributeSchema access (read of specific attribute)
SecurityEvent
| where TimeGenerated > ago(LookbackPeriod)
| where EventID == 4662
| where AccessMask == "0x10"           // Read Property
    or AccessMask == "0x100"           // Control Access (extended rights)
// Match on LAPS/GMSA specific property GUIDs or names
| where Properties has_any (
    "ms-Mcs-AdmPwd",
    "msDS-ManagedPassword",
    "2d1b333d-222b-14d0-ada8-00aa00c149d8",    // ms-Mcs-AdmPwd GUID
    "0e10c968-78fb-11d2-90d4-00c04f79dc55",    // Extended Rights — Certificate Enrollment
    "bf967a86-0de6-11d0-a285-00aa003049e2",    // ms-Mcs-AdmPwd property set GUID
    "e362ed86-b728-0842-b27d-2dea7a9df218"     // msDS-ManagedPassword
)
| extend
    Actor           = tolower(SubjectUserName),
    ActorDomain     = SubjectDomainName,
    TargetObject    = ObjectName,
    ActorNorm       = tolower(SubjectUserName),
    IsLAPSRead      = Properties has "ms-Mcs-AdmPwd",
    IsGMSARead      = Properties has "msDS-ManagedPassword",
    AttributeType   = case(
        Properties has "ms-Mcs-AdmPwd",            "LAPS_PlaintextPassword",
        Properties has "msDS-ManagedPassword",     "GMSA_ManagedPassword",
        Properties has "ms-Mcs-AdmPwdExpiration",  "LAPS_ExpirationTime",
        "SensitiveAttribute"
    )
| where not(ActorNorm has_any (LegitimateReaders))
// Exclude machine accounts doing self-read (expected during policy application)
| where not(ActorNorm endswith "$" and TargetObject has ActorNorm)
| summarize
    ReadCount       = count(),
    LAPSReads       = countif(IsLAPSRead),
    GMSAReads       = countif(IsGMSARead),
    TargetObjects   = make_set(TargetObject, 20),
    AttributeTypes  = make_set(AttributeType, 5),
    DCs             = make_set(Computer, 5),
    FirstRead       = min(TimeGenerated),
    LastRead        = max(TimeGenerated)
  by Actor, ActorDomain
| extend
    AccountFull = strcat(ActorDomain, "\\", Actor),
    RiskScore = (LAPSReads * 30)
              + (GMSAReads * 30)
              + (array_length(TargetObjects) * 5),
    Severity = case(
        array_length(TargetObjects) >= 5, "High - Mass_LAPS_GMSA_Harvest",
        LAPSReads >= 1 and GMSAReads >= 1,  "High - Both_LAPS_And_GMSA_Read",
        LAPSReads >= 1,                     "High - LAPS_Password_Read",
        GMSAReads >= 1,                     "High - GMSA_Password_Read",
        "Medium"
    )
| where ReadCount >= 1
| project
    TimeGenerated   = LastRead,
    AccountFull,
    Actor,
    ActorDomain,
    Severity,
    RiskScore,
    LAPSReads,
    GMSAReads,
    ReadCount,
    TargetObjects,
    AttributeTypes,
    DCs,
    FirstRead
| order by RiskScore desc

// ============================================================
// RULE-32 | AD Security: Accessibility Feature / IFEO Backdoor
// ============================================================
// Description:
//   Detects persistence/privilege escalation via Image File Execution Options
//   (IFEO) debugger hijacking of Windows accessibility binaries (Sticky Keys,
//   Utilman, Narrator, On-Screen Keyboard, Magnifier, Display Switch, ATBroker).
//   Attackers (e.g., Sticky-Keys-Slayer) replace or redirect sethc.exe/utilman.exe
//   to cmd.exe, allowing SYSTEM-level shell access from the Windows logon screen
//   via the accessibility shortcut keys — no credentials required.
//
//   Detection covers TWO attack vectors:
//     1. Registry modification to IFEO debugger key (EventID 4657)
//     2. Suspicious process spawn where accessibility binary is parent (EventID 4688)
//
// Mitre ATT&CK:
//   - T1546.008: Event Triggered Execution — Accessibility Features
//   - T1543:     Create or Modify System Process
//   - TA0003:    Persistence
//   - TA0004:    Privilege Escalation
//
// Data Sources: SecurityEvent (EventID 4657, 4688), DeviceProcessEvents
// Severity:     High
// Frequency:    Every 10 minutes | Lookback 10 minutes
// Alert Suppression: 4 hours per affected host
// ============================================================

// ──────────────────────────────────────────────────────────────
// PART 1 — Registry IFEO Debugger Key Write (EventID 4657)
//   Auditing prerequisite: Enable "Audit Registry" in Advanced Audit Policy
// ──────────────────────────────────────────────────────────────
let AccessibilityBinaries = dynamic([
    "sethc.exe",        // Sticky Keys (Shift x5)
    "utilman.exe",      // Utility Manager (Win+U)
    "osk.exe",          // On-Screen Keyboard
    "magnify.exe",      // Magnifier
    "narrator.exe",     // Narrator
    "displayswitch.exe",// Display Switch (Win+P)
    "atbroker.exe"      // Assistive Technology Broker
]);
let SuspiciousDebuggers = dynamic([
    "cmd.exe", "powershell.exe", "powershell_ise.exe",
    "pwsh.exe", "mshta.exe", "wscript.exe", "cscript.exe",
    "rundll32.exe", "regsvr32.exe", "msiexec.exe",
    "net.exe", "whoami.exe"
]);
// --- Vector 1: IFEO registry write ---
let IFEORegistryWrites = SecurityEvent
| where TimeGenerated >= ago(10m)
| where EventID == 4657
| where ObjectName has_any (
    @"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\sethc.exe",
    @"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\utilman.exe",
    @"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\osk.exe",
    @"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\magnify.exe",
    @"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\narrator.exe",
    @"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\displayswitch.exe",
    @"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\atbroker.exe"
)
| where ObjectValueName =~ "Debugger" or ObjectValueName =~ "GlobalFlag"
| extend
    Actor              = tolower(strcat(SubjectDomainName, "\\", SubjectUserName)),
    AffectedHost       = Computer,
    TargetKey          = ObjectName,
    ValueName          = ObjectValueName,
    NewValue           = NewValue,
    OldValue           = OldValue,
    DetectionVector    = "IFEO_RegistryWrite",
    MITRE_Technique    = "T1546.008"
| project
    TimeGenerated, AffectedHost, Actor,
    TargetKey, ValueName, OldValue, NewValue,
    DetectionVector, MITRE_Technique;
// --- Vector 2: Accessibility binary spawns shell (EventID 4688) ---
let AccessibilityShellSpawn = SecurityEvent
| where TimeGenerated >= ago(10m)
| where EventID == 4688
| extend
    ParentProcess = tolower(tostring(extract(@"([^\\]+)$", 1, ParentProcessName))),
    ChildProcess  = tolower(tostring(extract(@"([^\\]+)$", 1, NewProcessName)))
| where ParentProcess in~ (AccessibilityBinaries)
| where ChildProcess in~ (SuspiciousDebuggers)
| extend
    Actor              = tolower(strcat(SubjectDomainName, "\\", SubjectUserName)),
    AffectedHost       = Computer,
    TargetKey          = strcat("_AccessibilityParent:", ParentProcess),
    ValueName          = "ProcessSpawn",
    OldValue           = ParentProcess,
    NewValue           = strcat(NewProcessName, " ", CommandLine),
    DetectionVector    = "AccessibilityBinary_ShellSpawn",
    MITRE_Technique    = "T1546.008"
| project
    TimeGenerated, AffectedHost, Actor,
    TargetKey, ValueName, OldValue, NewValue,
    DetectionVector, MITRE_Technique;
// --- Vector 3: DeviceProcessEvents (MDE) - accessibility binary parent ---
let MDEAccessibilitySpawn = union isfuzzy=true (DeviceProcessEvents
| where TimeGenerated >= ago(10m)
| extend
    ParentBin = tolower(tostring(extract(@"([^\\]+)$", 1, InitiatingProcessFileName))),
    ChildBin  = tolower(FileName)
| where ParentBin in~ (AccessibilityBinaries)
| where ChildBin in~ (SuspiciousDebuggers)
| extend
    Actor              = tolower(strcat(InitiatingProcessAccountDomain, "\\", InitiatingProcessAccountName)),
    AffectedHost       = DeviceName,
    TargetKey          = strcat("_AccessibilityParent:", ParentBin),
    ValueName          = "ProcessSpawn",
    OldValue           = InitiatingProcessFileName,
    NewValue           = strcat(FolderPath, "\\", FileName, " | ", ProcessCommandLine),
    DetectionVector    = "MDE_AccessibilitySpawn",
    MITRE_Technique    = "T1546.008"
| project
    TimeGenerated, AffectedHost, Actor,
    TargetKey, ValueName, OldValue, NewValue,
    DetectionVector, MITRE_Technique);
// ──────────────────────────────────────────────────────────────
// UNION all vectors and finalize
// ──────────────────────────────────────────────────────────────
union IFEORegistryWrites, AccessibilityShellSpawn, MDEAccessibilitySpawn
| summarize
    FirstDetected   = min(TimeGenerated),
    LastDetected    = max(TimeGenerated),
    EventCount      = count(),
    Vectors         = make_set(DetectionVector),
    NewValues       = make_set(NewValue),
    OldValues       = make_set(OldValue),
    AffectedKeys    = make_set(TargetKey)
    by AffectedHost, Actor, MITRE_Technique
| extend
    Severity = iff(
        Vectors has "IFEO_RegistryWrite" and (Vectors has "AccessibilitySpawn" or Vectors has "MDE"),
        "Critical",   // Both registry write AND spawn observed — confirmed exploitation
        "High"        // Either vector alone is already high-confidence
    ),
    AlertName = strcat("Accessibility Feature Backdoor (IFEO): ", Actor, " on ", AffectedHost)
| project-reorder
    FirstDetected, LastDetected, Severity, AlertName,
    AffectedHost, Actor,
    Vectors, AffectedKeys, NewValues, OldValues,
    EventCount, MITRE_Technique

// =========================================================
// HUNT-04 | AD-ACL-Sensitive-Object-Timeline-30d
// Description : All DS Object Modification (5136) events on
//               sensitive AD objects over 30 days, annotated
//               with the likely attack technique for each
//               attribute/object combination.
//               Targets: AdminSDHolder, Domain root, DCs OU,
//               DA/EA/BA groups, krbtgt, ADCS templates.
// Period      : 30 days
// Use Case    : Privilege escalation forensics,
//               ACL backdoor audit, post-incident review
// Tables      : SecurityEvent
// =========================================================

let Period = 30d;

// Sensitive object DN patterns and associated risk
let SensitiveObjects = datatable(Pattern:string, ObjectDescription:string, BaseSeverity:string)
[
    "CN=AdminSDHolder,CN=System", "AdminSDHolder (SDProp target)", "Critical",
    "CN=Domain Admins",           "Domain Admins group",           "Critical",
    "CN=Enterprise Admins",       "Enterprise Admins group",       "Critical",
    "CN=Schema Admins",           "Schema Admins group",           "Critical",
    "CN=krbtgt",                  "krbtgt account",                "Critical",
    "CN=Administrators,CN=Builtin","Built-in Administrators group", "Critical",
    "CN=Backup Operators,CN=Builtin","Backup Operators group",     "High",
    "CN=Account Operators,CN=Builtin","Account Operators group",   "High",
    "CN=Server Operators,CN=Builtin", "Server Operators group",    "High",
    "OU=Domain Controllers",      "Domain Controllers OU",         "Critical",
    "CN=Certificate Templates",   "ADCS Certificate Templates",    "High",
    "CN=Sites,CN=Configuration",  "AD Sites Configuration",        "High"
];

// Attribute-to-technique mapping
let AttrTechniques = datatable(Attribute:string, Technique:string)
[
    "msDS-AllowedToActOnBehalfOfOtherIdentity", "RBCD Setup (T1134.001)",
    "msDS-KeyCredentialLink",                   "Shadow Credentials (T1556.006)",
    "sIDHistory",                               "SID History Injection (T1134.005)",
    "ntSecurityDescriptor",                     "ACL Backdoor / WriteDACL",
    "servicePrincipalName",                     "Targeted Kerberoasting (T1558.003)",
    "userAccountControl",                       "Account Flag Modification",
    "member",                                   "Group Membership Add (T1098)",
    "pwdLastSet",                               "Password Reset (T1098)",
    "scriptPath",                               "Logon Script Hijack (T1037.001)",
    "profilePath",                              "Profile Path Coercion (NTLMv2 capture)",
    "dNSHostName",                              "Certifried / DNS Manipulation",
    "msPKI-Certificate-Name-Flag",              "ADCS ESC1 Template Modification",
    "gPCFileSysPath",                           "GPO SYSVOL Path Modification (T1484.001)"
];

SecurityEvent
| where TimeGenerated > ago(Period)
| where EventID == 5136
// Match against sensitive object patterns
| extend _joinkey = 1
| join kind=inner (SensitiveObjects | extend _joinkey = 1) on _joinkey
| where ObjectName contains Pattern
| project-away _joinkey, _joinkey1
| extend
    ActorAccount   = strcat(SubjectDomainName, "\\", SubjectUserName),
    ModifiedAttrib = tostring(column_ifexists("AttributeLDAPDisplayName", ""))
// Annotate with known technique
| join kind=leftouter (AttrTechniques)
    on $left.ModifiedAttrib == $right.Attribute
| extend
    AttackTechnique = coalesce(Technique, "Unknown — Review Manually"),
    OperationDesc   = case(
        OperationType == "%%14674", "Write/Add",
        OperationType == "%%14675", "Delete",
        OperationType == "%%14676", "Delete All Values",
        OperationType
    ),
    EffectiveSeverity = case(
        BaseSeverity == "Critical" and Technique != "",  "Critical",
        BaseSeverity == "Critical",                      "High",
        "Medium"
    )
| project
    TimeGenerated,
    EffectiveSeverity,
    ObjectDescription,
    AttackTechnique,
    ModifiedAttrib,
    OperationDesc,
    ActorAccount,
    ObjectName,
    Computer
| order by EffectiveSeverity asc, TimeGenerated desc

// =========================================================
// HUNT-21 | AD-Coercion-Attack-Indicators-30d
// Description : Hunts for signals that coercion attacks
//               (PrinterBug/MS-RPRN, PetitPotam/MS-EFSR,
//               DFSCoerce/MS-DFSNM, ShadowCoerce/MS-FSRVP)
//               were attempted. Looks for DC machine account
//               authentications (4624 Type3 Kerberos) to
//               non-DC hosts — the tell-tale sign that a
//               DC was coerced to authenticate outbound.
//               Also surfaces NTLM relay indicators such
//               as rapid machine account logons to multiple
//               distinct targets within 1-minute windows.
// Period      : 30 days
// Use Case    : Coercion attack detection, NTLM relay
//               chain hunting, Unconstrained Delegation
//               abuse confirmation
// Tables      : SecurityEvent
// =========================================================

let Period = 30d;

// Build DC list
let DCHostSet = SecurityEvent
    | where TimeGenerated > ago(Period)
    | where EventID == 4768   // DCs issue TGTs
    | summarize by DCName = toupper(Computer);

// Machine accounts with Unconstrained Delegation flag (proxy from 4742)
// Unconstrained delegation enabled = TrustedForDelegation set
let UnconstDelegHosts = SecurityEvent
    | where TimeGenerated > ago(Period)
    | where EventID in (4742, 4741)
    | where NewUacValue has "TRUSTED_FOR_DELEGATION"
    or OldUacValue !has "TRUSTED_FOR_DELEGATION" and NewUacValue has "TRUSTED_FOR_DELEGATION"
    | summarize by UnconstHost = toupper(TargetUserName);

// DC machine account logons to non-DC hosts (the coercion outcome)
let CoercedLogons = SecurityEvent
    | where TimeGenerated > ago(Period)
    | where EventID == 4624
    | where LogonType == 3                    // network logon
    | where TargetUserName endswith "$"       // machine account
    | extend
        MachineNorm  = toupper(trim_end("$", TargetUserName)),
        TargetHost   = toupper(Computer),
        SourceIP     = IpAddress,
        AuthPackage  = AuthenticationPackageName
    // Filter to DC machine accounts only
    | join kind=inner (DCHostSet) on $left.MachineNorm == $right.DCName
    // Exclude DC-to-DC logons
    | join kind=leftanti (DCHostSet) on $left.TargetHost == $right.DCName;

// Correlate with unconstrained delegation hosts as coercion targets
CoercedLogons
| join kind=leftouter (UnconstDelegHosts)
    on $left.TargetHost == $right.UnconstHost
| extend IsCoercingToUnconstrained = isnotempty(UnconstHost)
| summarize
    CoercedLogonCount     = count(),
    UniqueCoercingDCs     = dcount(MachineNorm),
    UniqueTargetHosts     = dcount(TargetHost),
    CoercingDCs           = make_set(MachineNorm, 20),
    TargetHosts           = make_set(TargetHost, 20),
    TargetsWithUnconst    = make_set_if(TargetHost, IsCoercingToUnconstrained, 10),
    SourceIPs             = make_set(SourceIP, 20),
    AuthPackages          = make_set(AuthPackage, 5),
    FirstCoercion         = min(TimeGenerated),
    LastCoercion          = max(TimeGenerated)
  by bin(TimeGenerated, 1h)
| extend
    RiskScore = (CoercedLogonCount * 10)
              + (array_length(TargetsWithUnconst) * 50)
              + (UniqueCoercingDCs * 20),
    RiskLevel = case(
        array_length(TargetsWithUnconst) >= 1,
            "Critical - DC_Coerced_To_Unconstrained_Delegation_Host",
        UniqueCoercingDCs >= 2,
            "High - Multiple_DCs_Coerced",
        CoercedLogonCount >= 3,
            "High - Repeated_DC_Outbound_Auth",
        CoercedLogonCount >= 1,
            "Medium - DC_Outbound_Auth_To_NonDC",
        "Low"
    ),
    CoercionProtocol = case(
        // Heuristic: cannot determine protocol from SecurityEvent alone
        // Flag for manual investigation
        array_length(TargetsWithUnconst) >= 1, "Likely_PrinterBug_Or_PetitPotam_To_UnconstDC",
        "Possible_Coercion_Via_MS-RPRN_MS-EFSR_MS-DFSNM"
    )
| project
    TimeWindow      = TimeGenerated,
    RiskLevel,
    RiskScore,
    CoercionProtocol,
    CoercedLogonCount,
    UniqueCoercingDCs,
    CoercingDCs,
    UniqueTargetHosts,
    TargetHosts,
    TargetsWithUnconst,
    SourceIPs
| order by RiskScore desc

// ============================================================
// HUNT-27 | AD Hunting: NTLMv1 Downgrade and Hash Coercion Indicators
// ============================================================
// Description:
//   Hunts for NTLMv1 authentication events, which indicate either:
//     (a) Legacy clients or servers with LAN Manager compatibility level < 3 (misconfiguration)
//     (b) Deliberate NTLMv1 downgrade attacks using tools such as:
//         - NetNTLMtoSilverTicket (force NTLMv1 → crack → Silver Ticket)
//         - ntlm_theft / Bad-Pdf (document-based UNC path NTLM capture)
//         - Responder with NTLMv1 challenge forcing
//         - InternalMonologue (NTLMSSP without LSASS access)
//
//   NTLMv1 hashes can be cracked in seconds using rainbow tables or ASIC hardware.
//   A cracked NTLMv1 hash gives the attacker the NT hash, which enables:
//     - Pass-the-Hash (PTH) attacks
//     - Silver Ticket creation for specific services (no KDC needed)
//     - DCSYNC if the hash belongs to a domain controller machine account
//
//   Discovery of NTLMv1 use in a modern domain is itself an IOC — most
//   organizations should have NTLMv1 fully disabled via GPO.
//
// Mitre ATT&CK:
//   - T1557.001: Adversary-in-the-Middle — LLMNR/NBT-NS Poisoning
//   - T1550.002: Use Alternate Authentication Material — Pass-the-Hash
//   - T1212:     Exploitation for Credential Access
//   - T1171:     Network Share Discovery (via forced auth to attacker share)
//
// Data Sources: SecurityEvent (EventID 4624, 4776)
// Query Period: 30 days
// Hunting Focus: NTLMv1 auth events, client concentration, privileged accounts
// ============================================================

// ──────────────────────────────────────────────────────────────
// PART 1 — NTLMv1 Logon Events (EventID 4624, AuthProcess = NTLM, Package = NTLM V1)
//   EventID 4624: An account was successfully logged on
//   LmPackageName = "NTLM V1" confirms NTLMv1 was used (not NTLMv2)
//   Logon Type 3 = Network logon (most common for NTLM relay)
// ──────────────────────────────────────────────────────────────
let LookbackPeriod = 30d;
let PrivilegedGroups = dynamic(["Domain Admins", "Enterprise Admins", "Schema Admins", "Administrators"]);
let ExpectedNTLMv1Hosts = dynamic([
    // Add known legacy hosts that legitimately use NTLMv1 if any:
    // "legacy-server01", "oldprint-server"
    ""
]);
// --- EventID 4624 NTLMv1 logons ---
let NTLMv1Logons = SecurityEvent
| where TimeGenerated >= ago(LookbackPeriod)
| where EventID == 4624
| where AuthenticationPackageName =~ "NTLM"
| where LmPackageName =~ "NTLM V1" or LmPackageName =~ "NTLM V1 with Client Challenge"
| where LogonType in (3, 9, 10)  // Network, NewCredentials, RemoteInteractive
| where AccountName !endswith "$"  // Exclude machine account self-auth for now (see Part 2)
| where not(WorkstationName in~ (ExpectedNTLMv1Hosts))
| extend
    Actor              = tolower(strcat(TargetDomainName, "\\", TargetUserName)),
    AuthenticatedTo    = Computer,
    SourceDevice       = WorkstationName,
    SourceIP           = IpAddress,
    AuthPackage        = LmPackageName,
    LogonTypeName      = case(
        LogonType == 3,  "Network",
        LogonType == 9,  "NewCredentials",
        LogonType == 10, "RemoteInteractive",
        tostring(LogonType)
    ),
    IsPrivilegedAccount = AccountName in~ (PrivilegedGroups),  // Approximate; refine with identity data
    MITRE_Technique     = "T1557.001 + T1550.002"
| project
    TimeGenerated, Actor, AuthenticatedTo, SourceDevice, SourceIP,
    AuthPackage, LogonTypeName, LogonType,
    IsPrivilegedAccount, MITRE_Technique;
// --- EventID 4776 NTLM Credential Validation (for DC-side visibility) ---
let NTLMv1Validation = SecurityEvent
| where TimeGenerated >= ago(LookbackPeriod)
| where EventID == 4776
| extend
    Actor           = tolower(strcat(SubjectDomainName, "\\", TargetUserName)),
    AuthenticatedTo = Computer,  // This fires on the DC
    SourceDevice    = WorkstationName,
    SourceIP        = "",         // 4776 does not include IP (use 4624 for IP data)
    AuthPackage     = "NTLM-Validation-DC",
    LogonTypeName   = "DCValidation",
    IsPrivilegedAccount = false,
    MITRE_Technique = "T1557.001"
// Note: 4776 does not expose LmPackageName; filter by known NTLMv1 source via join
| project
    TimeGenerated, Actor, AuthenticatedTo, SourceDevice, SourceIP,
    AuthPackage, LogonTypeName, LogonType = int(0),
    IsPrivilegedAccount, MITRE_Technique;
// ──────────────────────────────────────────────────────────────
// PART 2 — Machine Account NTLMv1 (higher risk: enables Silver Ticket to service)
// ──────────────────────────────────────────────────────────────
let NTLMv1MachineAccounts = SecurityEvent
| where TimeGenerated >= ago(LookbackPeriod)
| where EventID == 4624
| where AuthenticationPackageName =~ "NTLM"
| where LmPackageName =~ "NTLM V1" or LmPackageName =~ "NTLM V1 with Client Challenge"
| where LogonType in (3, 9)
| where AccountName endswith "$"
| extend
    Actor              = tolower(strcat(TargetDomainName, "\\", TargetUserName)),
    AuthenticatedTo    = Computer,
    SourceDevice       = WorkstationName,
    SourceIP           = IpAddress,
    AuthPackage        = LmPackageName,
    LogonTypeName      = "Network_MachineAcct",
    IsPrivilegedAccount = true,   // Machine accounts with NTLMv1 = potential Silver Ticket
    MITRE_Technique    = "T1212 + T1550.002"
| project
    TimeGenerated, Actor, AuthenticatedTo, SourceDevice, SourceIP,
    AuthPackage, LogonTypeName, LogonType,
    IsPrivilegedAccount, MITRE_Technique;
// ──────────────────────────────────────────────────────────────
// PART 3 — Document-based NTLM Capture Signal (UNC path auto-auth)
//   Detects when Office/PDF process (winword, excel, acrobat, etc.) triggers
//   an outbound NTLM auth — typical of ntlm_theft / Bad-Pdf document tricks
// ──────────────────────────────────────────────────────────────
let DocumentNTLMCapture = union isfuzzy=true (DeviceNetworkEvents
| where TimeGenerated >= ago(LookbackPeriod)
| where InitiatingProcessFileName in~ (
    "WINWORD.EXE", "EXCEL.XL", "POWERPNT.EXE",
    "Acrobat.exe", "AcroRd32.exe", "FoxitPDFReader.exe",
    "msedge.exe", "chrome.exe", "firefox.exe",  // For WPAD / UNC in browser
    "outlook.exe"
)
| where RemotePort == 445 or RemotePort == 139  // SMB for NTLM capture
| where RemoteIPType != "Loopback"
| where ActionType =~ "ConnectionSuccess"
| extend
    Actor              = tolower(strcat(InitiatingProcessAccountDomain, "\\", InitiatingProcessAccountName)),
    AuthenticatedTo    = DeviceName,
    SourceDevice       = DeviceName,
    SourceIP           = LocalIP,
    AuthPackage        = "SMB-NTLM-via-Document",
    LogonTypeName      = "DocumentTriggered",
    LogonType          = int(-1),
    IsPrivilegedAccount = false,
    MITRE_Technique    = "T1171 + T1557.001",
    RemoteTarget       = strcat(RemoteIP, ":", RemotePort),
    TriggerProcess     = InitiatingProcessFileName
| project
    TimeGenerated, Actor, AuthenticatedTo = RemoteTarget, SourceDevice, SourceIP,
    AuthPackage, LogonTypeName, LogonType,
    IsPrivilegedAccount, MITRE_Technique),
    (print _placeholder = "" | where 1==0);
// ──────────────────────────────────────────────────────────────
// UNION and summarize — hunting view
// ──────────────────────────────────────────────────────────────
union NTLMv1Logons, NTLMv1MachineAccounts, DocumentNTLMCapture
| summarize
    FirstSeen        = min(TimeGenerated),
    LastSeen         = max(TimeGenerated),
    TotalEvents      = count(),
    UniqueTargets    = dcount(AuthenticatedTo),
    UniqueSourceIPs  = dcount(SourceIP),
    Targets          = make_set(AuthenticatedTo, 20),
    SourceIPs        = make_set(SourceIP, 10),
    AuthPackages     = make_set(AuthPackage),
    LogonTypes       = make_set(LogonTypeName),
    IsPrivileged     = max(IsPrivilegedAccount)
    by Actor, SourceDevice, MITRE_Technique
| extend
    RiskScore = case(
        IsPrivileged == true,                     "Critical",  // Privileged/machine NTLMv1 → Silver Ticket risk
        UniqueTargets > 5,                        "High",      // Broad NTLMv1 from one source
        AuthPackages has "DocumentTriggered",     "High",      // Document-triggered capture
        "Medium"
    ),
    AttackSurface = strcat(
        "Actor: ", Actor, " | Sources: ", tostring(UniqueSourceIPs),
        " | Targets: ", tostring(UniqueTargets)
    )
| project-reorder
    FirstSeen, LastSeen, RiskScore,
    Actor, SourceDevice, SourceIPs,
    Targets, UniqueTargets,
    AuthPackages, LogonTypes,
    TotalEvents, IsPrivileged, AttackSurface, MITRE_Technique
| sort by RiskScore asc, TotalEvents desc   // Critical/High first, then by volume
// ──────────────────────────────────────────────────────────────
// ANALYST NOTES:
// - Any NTLMv1 event in a modern AD domain warrants investigation.
//   Hardened domains running LAN Manager Authentication Level = 5 (Send NTLMv2 only,
//   refuse LM & NTLM) should see zero 4624 events with LmPackageName = "NTLM V1".
// - Key remediation: Set GPO: Computer Configuration > Windows Settings > Security
//   Settings > Local Policies > Security Options > Network security: LAN Manager
//   authentication level = "Send NTLMv2 response only. Refuse LM & NTLM"
// - Document-triggered SMB connections to external IPs are IOC regardless of NTLMv1.
// ──────────────────────────────────────────────────────────────

// ============================================================
// HUNT-28 | AD Hunting: RDP Session Hijacking and Reconnection Anomaly
// ============================================================
// Description:
//   Hunts for RDP session hijacking patterns, primarily targeting the technique
//   used by tools such as SharpRDPHijack — which takeovers disconnected RDP
//   sessions of other users (including administrators) without needing credentials.
//
//   Attack chain:
//     1. Attacker gains SYSTEM-level access (e.g., via SeImpersonatePrivilege or
//        existing session)
//     2. Attacker enumerates disconnected RDP sessions: `query session`
//     3. Tools like tscon.exe redirect the target session to attacker's session
//        — EventID 4778 fires on the DC/target for the "reconnect"
//        — The original user (EventID 4779) shows a disconnect from their IP
//        — The hijack shows the NEW source reconnecting to the same session
//
//   Key signals hunted:
//     - Session reconnect (4778) immediately after disconnect (4779) for same account
//       from a DIFFERENT source IP — the "handoff" pattern
//     - tscon.exe or SharpRDPHijack process execution around session events
//     - Privileged accounts (Domain Admins, svc-* accounts) subjected to session churn
//     - RDP sessions opened to unexpected internal hosts (lateral movement indicator)
//
// Mitre ATT&CK:
//   - T1563.002: Remote Service Session Hijacking — RDP Hijacking
//   - T1078:     Valid Accounts (hijacked session runs as victim account)
//   - TA0008:    Lateral Movement
//   - TA0005:    Defense Evasion (operations appear under victim identity)
//
// Data Sources: SecurityEvent (EventID 4778, 4779, 4688), DeviceProcessEvents
// Query Period: 30 days
// Hunting Focus: Session IP shifts, tscon.exe execution, privileged account churn
// ============================================================

let LookbackPeriod = 30d;
let SessionHandoffWindow = 5m;   // Max time between disconnect and hijack reconnect
let KnownJumpHosts = dynamic([   // Legitimate IT jump boxes / VDI hosts — customize per environment
    // "jumphost01", "vdi-gateway01"
    ""
]);
let PrivilegedAccountPatterns = dynamic([
    "admin", "svc-", "service", "backup", "-adm", "_adm"
]);
// ──────────────────────────────────────────────────────────────
// PART 1 — EventID 4778 / 4779 Session Reconnect and Disconnect Events
//   4778 = A session was reconnected to a Window Station
//   4779 = A session was disconnected from a Window Station
// ──────────────────────────────────────────────────────────────
let SessionDisconnects = SecurityEvent
| where TimeGenerated >= ago(LookbackPeriod)
| where EventID == 4779
| extend
    SessionUser     = tolower(strcat(AccountDomain, "\\", AccountName)),
    SessionHost     = Computer,
    SessionName     = tostring(extract(@"SessionName:\s+(\S+)", 1, EventData)),
    DisconnectIP    = IpAddress,
    DisconnectTime  = TimeGenerated
| project DisconnectTime, SessionUser, SessionHost, SessionName, DisconnectIP;
let SessionReconnects = SecurityEvent
| where TimeGenerated >= ago(LookbackPeriod)
| where EventID == 4778
| extend
    SessionUser     = tolower(strcat(AccountDomain, "\\", AccountName)),
    SessionHost     = Computer,
    SessionName     = tostring(extract(@"SessionName:\s+(\S+)", 1, EventData)),
    ReconnectIP     = IpAddress,
    ReconnectTime   = TimeGenerated
| project ReconnectTime, SessionUser, SessionHost, SessionName, ReconnectIP;
// --- Join: Find disconnects followed by reconnects from different IP ---
let SessionHandoff = SessionDisconnects
| join kind=inner SessionReconnects on SessionUser, SessionHost
| where ReconnectTime > DisconnectTime
| where ReconnectTime < datetime_add("minute", toint(SessionHandoffWindow / 1m + 0.5), DisconnectTime)
| where ReconnectIP != DisconnectIP                // Source IP changed — key hijack signal
| where isnotempty(ReconnectIP)
| where isnotempty(DisconnectIP)
| where not(ReconnectIP has "127.0.0.1")
| where not(SessionHost in~ (KnownJumpHosts))
| extend
    TimeDeltaSeconds = datetime_diff("second", ReconnectTime, DisconnectTime),
    IsPrivilegedTarget = SessionUser has_any (PrivilegedAccountPatterns)
| extend
    HijackSignal = strcat(
        SessionUser, " disconnected from ", DisconnectIP,
        " → reconnected from ", ReconnectIP,
        " within ", tostring(TimeDeltaSeconds), "s"
    ),
    MITRE_Technique = "T1563.002"
| project
    DisconnectTime, ReconnectTime, TimeDeltaSeconds,
    SessionUser, SessionHost, SessionName,
    DisconnectIP, ReconnectIP,
    IsPrivilegedTarget, HijackSignal, MITRE_Technique;
// ──────────────────────────────────────────────────────────────
// PART 2 — tscon.exe Execution (the core mechanism for RDP session handoff)
//   tscon.exe <sessionID> /dest:<current_session> redirects another session
//   Legitimate use: reconnecting your own session — rare in production
//   Attacker use: redirecting victim session to attacker terminal
// ──────────────────────────────────────────────────────────────
let TsconExecution = SecurityEvent
| where TimeGenerated >= ago(LookbackPeriod)
| where EventID == 4688
| where NewProcessName endswith "\\tscon.exe"
| extend
    Actor           = tolower(strcat(SubjectDomainName, "\\", SubjectUserName)),
    AffectedHost    = Computer,
    CmdLine         = CommandLine,
    SessionID_arg   = extract(@"tscon\.exe\s+(\d+)", 1, CommandLine),
    Dest_arg        = extract(@"/dest:(\S+)", 1, CommandLine),
    MITRE_Technique = "T1563.002"
| where Actor !has "system"  // Filter out normal system-level tscon (e.g., logon service)
| project
    TimeGenerated, AffectedHost, Actor,
    CmdLine, SessionID_arg, Dest_arg, MITRE_Technique;
// --- MDE variant ---
let MDETscon = union isfuzzy=true (DeviceProcessEvents
| where TimeGenerated >= ago(LookbackPeriod)
| where FileName =~ "tscon.exe"
| extend
    Actor           = tolower(strcat(InitiatingProcessAccountDomain, "\\", InitiatingProcessAccountName)),
    AffectedHost    = DeviceName,
    CmdLine         = ProcessCommandLine,
    SessionID_arg   = extract(@"tscon\.exe\s+(\d+)", 1, ProcessCommandLine),
    Dest_arg        = extract(@"/dest:(\S+)", 1, ProcessCommandLine),
    MITRE_Technique = "T1563.002"
| where Actor !has "system"
| project
    TimeGenerated, AffectedHost, Actor,
    CmdLine, SessionID_arg, Dest_arg, MITRE_Technique),
    (print _placeholder = "" | where 1==0);
// ──────────────────────────────────────────────────────────────
// PART 3 — High-frequency 4779 Disconnect (session churn — reconnaissance)
//   Attacker using `query session` or SharpRDPHijack may cycle through sessions
//   causing unusually high disconnect/reconnect rates on a given host
// ──────────────────────────────────────────────────────────────
let SessionChurn = SecurityEvent
| where TimeGenerated >= ago(LookbackPeriod)
| where EventID in (4778, 4779)
| summarize
    SessionEvents   = count(),
    DisconnectCount = countif(EventID == 4779),
    ReconnectCount  = countif(EventID == 4778),
    UniqueIPs       = dcount(IpAddress),
    IPList          = make_set(IpAddress, 10),
    AffectedUsers   = make_set(strcat(AccountDomain, "\\", AccountName), 10)
    by Computer, bin(TimeGenerated, 1h)
| where DisconnectCount >= 5 or UniqueIPs >= 3   // Abnormal session churn
| extend
    AffectedHost    = Computer,
    MITRE_Technique = "T1563.002",
    HuntNote        = strcat(
        tostring(DisconnectCount), " disconnects / ",
        tostring(ReconnectCount), " reconnects in 1h window from ",
        tostring(UniqueIPs), " unique source IPs"
    )
| project
    TimeGenerated, AffectedHost, AffectedUsers,
    DisconnectCount, ReconnectCount, UniqueIPs, IPList,
    HuntNote, MITRE_Technique;
// ──────────────────────────────────────────────────────────────
// PART 4 — RDP Lateral Movement (RDP logons from non-standard hosts in internal network)
//   Specifically: accounts logging in via RDP (Logon Type 10) to multiple hosts
//   in short succession — lateral movement via hijacked or stolen sessions
// ──────────────────────────────────────────────────────────────
let RDPLateralMovement = SecurityEvent
| where TimeGenerated >= ago(LookbackPeriod)
| where EventID == 4624
| where LogonType == 10  // RemoteInteractive = RDP
| where AuthenticationPackageName =~ "Kerberos" or AuthenticationPackageName =~ "NTLM"
| extend
    Actor           = tolower(strcat(TargetDomainName, "\\", TargetUserName)),
    TargetHost      = Computer,
    SourceIP        = IpAddress
| where Actor !endswith "$"  // Exclude machine self-auth
| summarize
    FirstSeen       = min(TimeGenerated),
    LastSeen        = max(TimeGenerated),
    UniqueHosts     = dcount(TargetHost),
    Hosts           = make_set(TargetHost, 20),
    UniqueSourceIPs = dcount(SourceIP),
    SourceIPs       = make_set(SourceIP, 10),
    TotalRDPLogons  = count()
    by Actor
| where UniqueHosts >= 3   // RDP to 3+ hosts = lateral movement indicator
| extend
    MITRE_Technique = "T1563.002 + T1078",
    HuntNote        = strcat(
        tostring(UniqueHosts), " RDP targets from ",
        tostring(UniqueSourceIPs), " source IPs over ",
        tostring(TotalRDPLogons), " total sessions"
    )
| project-reorder
    FirstSeen, LastSeen, Actor,
    UniqueHosts, Hosts,
    UniqueSourceIPs, SourceIPs,
    TotalRDPLogons, HuntNote, MITRE_Technique;
// ──────────────────────────────────────────────────────────────
// AGGREGATE HUNTING OUTPUT — Session Handoff anomalies (primary signal)
// ──────────────────────────────────────────────────────────────
SessionHandoff
| extend RiskScore = iff(IsPrivilegedTarget, "Critical", "High")
| union (
    TsconExecution | extend RiskScore = "High", HijackSignal = strcat("tscon.exe executed: ", CmdLine), IsPrivilegedTarget = false, SessionUser = Actor, SessionHost = AffectedHost, DisconnectIP = "", ReconnectIP = "", SessionName = "", DisconnectTime = TimeGenerated, ReconnectTime = TimeGenerated, TimeDeltaSeconds = 0
)
| union (
    MDETscon | extend RiskScore = "High", HijackSignal = strcat("tscon.exe (MDE): ", CmdLine), IsPrivilegedTarget = false, SessionUser = Actor, SessionHost = AffectedHost, DisconnectIP = "", ReconnectIP = "", SessionName = "", DisconnectTime = TimeGenerated, ReconnectTime = TimeGenerated, TimeDeltaSeconds = 0
)
| project-reorder
    DisconnectTime, ReconnectTime, RiskScore,
    SessionUser, SessionHost, SessionName,
    DisconnectIP, ReconnectIP, TimeDeltaSeconds,
    IsPrivilegedTarget, HijackSignal, MITRE_Technique
| sort by RiskScore asc, DisconnectTime desc
// ──────────────────────────────────────────────────────────────
// To run session churn or RDP lateral movement analyses, 
// comment out the union above and run each sub-query individually:
//   - SessionChurn
//   - RDPLateralMovement
// ──────────────────────────────────────────────────────────────

// ============================================================
// HUNT-29 | AD Hunting: Legacy NTLM Authentication Usage
// ============================================================
// Description:
//   Comprehensive hunt for all legacy NTLM authentication patterns in the
//   domain over the past 30 days. Covers three related attack surfaces:
//
//   1. NTLMv1 logons (EventID 4624 with LmPackageName = "NTLM V1 / LM")
//      - NTLMv1 hashes are crackable in seconds via rainbow tables or hardware
//      - Cracked hash → NT hash → Pass-the-Hash, Silver Ticket creation, DCSync
//      - Expected count in hardened domains: ZERO
//
//   2. Pure-NTLM accounts — accounts that only authenticate via NTLM, never Kerberos
//      - Strong indicator of legacy applications, misconfig, or forced downgrade
//      - No Kerberos means no SPN enforcement, no ticket lifetime controls
//
//   3. NTLM authentication volume trend — for remediation tracking and
//      detecting sudden spikes that indicate active relay/downgrade attacks
//
// Key hardening metric:
//   GPO: Computer Config > Windows Settings > Security Settings > Local Policies
//   > Security Options > "Network security: LAN Manager authentication level"
//   Should be set to: "Send NTLMv2 response only. Refuse LM & NTLM"
//   (Level 5 — rejects incoming NTLMv1, forces NTLMv2 for outbound)
//
// Mitre ATT&CK:
//   - T1557.001: Adversary-in-the-Middle — LLMNR/NBT-NS Poisoning and SMB Relay
//   - T1550.002: Use Alternate Authentication Material — Pass-the-Hash
//   - T1212:     Exploitation for Credential Access (hash cracking to NT hash)
//   - T1040:     Network Sniffing (NTLMv1 capture via Responder/ntlm_theft)
//
// Data Sources: SecurityEvent (EventID 4624, 4776)
// Query Period: 30 days
// Hunting Focus: NTLMv1 logons, NTLM-only accounts, protocol downgrade patterns
// ============================================================

let LookbackPeriod = 30d;

// Accounts/hosts explicitly excluded from alerting (known legacy exceptions)
let LegacyNTLMExclusions = dynamic([
    // Add confirmed legacy systems that require NTLMv1 for business reasons:
    // "legacy-print01", "old-scanner-dev"
    ""
]);

// ──────────────────────────────────────────────────────────────
// PART 1 — NTLMv1 Logon Events
//   LmPackageName values:
//     "LM"                          → LAN Manager (prehistoric — NT 3.x era)
//     "NTLM V1"                     → NTLMv1 (crackable offline in seconds)
//     "NTLM V1 with Client Challenge"→ NTLMv1 with ESS — still crackable
//     "NTLM V2"                     → NTLMv2 (acceptable)
// ──────────────────────────────────────────────────────────────
let NTLMv1Events = SecurityEvent
    | where TimeGenerated >= ago(LookbackPeriod)
    | where EventID == 4624
    | where AuthenticationPackageName =~ "NTLM"
    | where LmPackageName in ("LM", "NTLM V1", "NTLM V1 with Client Challenge")
    | where LogonType in (3, 9, 10)       // Network, NewCredentials, RemoteInteractive
    | where not(WorkstationName in~ (LegacyNTLMExclusions))
    | extend
        Account          = tolower(strcat(TargetDomainName, "\\", TargetUserName)),
        SourceHost       = WorkstationName,
        DestHost         = Computer,
        SourceIP         = IpAddress,
        NTLMVersion      = LmPackageName,
        IsMachineAccount = TargetUserName endswith "$",
        LogonTypeName    = case(
            LogonType == 3,  "Network",
            LogonType == 9,  "NewCredentials",
            LogonType == 10, "RemoteInteractive",
            tostring(LogonType));

// ──────────────────────────────────────────────────────────────
// PART 2 — Per-Account NTLMv1 Summary with Risk Scoring
// ──────────────────────────────────────────────────────────────
let NTLMv1Summary = NTLMv1Events
    | summarize
        FirstSeen          = min(TimeGenerated),
        LastSeen           = max(TimeGenerated),
        TotalEvents        = count(),
        UniqueDestHosts    = dcount(DestHost),
        UniqueSourceIPs    = dcount(SourceIP),
        DestHosts          = make_set(DestHost, 20),
        SourceIPs          = make_set(SourceIP, 10),
        SourceHosts        = make_set(SourceHost, 10),
        NTLMVersions       = make_set(NTLMVersion),
        LogonTypes         = make_set(LogonTypeName),
        IsMachineAccount   = max(toint(IsMachineAccount))
        by Account
    | extend
        RiskScore = (
            iff(IsMachineAccount == 1,         50, 0) +  // Machine account = Silver Ticket risk
            iff(UniqueDestHosts >= 5,           30, 0) +  // Spreading across many hosts = lateral movement
            iff(UniqueSourceIPs >= 3,           20, 0) +  // Multiple sources = relay or broad misconfiguration
            iff(NTLMVersions has "LM",          20, 0) +  // Pure LM = worst case
            iff(TotalEvents >= 100,             15, 0)    // High volume
        ),
        RiskLevel = case(
            IsMachineAccount == 1,
                "Critical — Machine account NTLMv1 enables Silver Ticket without cracking (NT hash exposed)",
            UniqueDestHosts >= 10,
                "High — NTLMv1 lateral movement spread across 10+ hosts",
            UniqueDestHosts >= 3,
                "High — NTLMv1 spread across multiple hosts",
            TotalEvents >= 50,
                "Medium — High-volume NTLMv1 from single source",
            "Low — NTLMv1 detected, investigate legacy system"
        );

// ──────────────────────────────────────────────────────────────
// PART 3 — NTLM-Only Accounts (no Kerberos observed — pure NTLM)
//   These accounts have either:
//     - No SPN set (old service accounts)
//     - msDS-SupportedEncryptionTypes = NTLM only
//     - Forced NTLM by relay attack (source is attacker's tool)
// ──────────────────────────────────────────────────────────────
let KerberosAccounts = SecurityEvent
    | where TimeGenerated >= ago(LookbackPeriod)
    | where EventID == 4624
    | where AuthenticationPackageName =~ "Kerberos"
    | where LogonType in (3, 9, 10)
    | summarize KerberosLogons = count() by AccountKey = tolower(TargetUserName);

let AllNTLMAccounts = SecurityEvent
    | where TimeGenerated >= ago(LookbackPeriod)
    | where EventID == 4624
    | where AuthenticationPackageName =~ "NTLM"
    | where LogonType in (3, 9, 10)
    | where TargetUserName !in~ ("ANONYMOUS LOGON", "IUSR", "IWAN_")
    | where not(WorkstationName in~ (LegacyNTLMExclusions))
    | summarize
        NTLMLogons       = count(),
        UniqueTargets    = dcount(Computer),
        Targets          = make_set(Computer, 15),
        SourceIPs        = make_set(IpAddress, 10),
        NTLMPackages     = make_set(LmPackageName),
        FirstSeen        = min(TimeGenerated),
        LastSeen         = max(TimeGenerated)
        by AccountKey = tolower(TargetUserName), Domain = TargetDomainName
    | join kind=leftouter (KerberosAccounts) on AccountKey
    | extend
        KerberosLogons    = coalesce(KerberosLogons, 0),
        TotalAuth         = NTLMLogons + coalesce(KerberosLogons, 0)
    | extend
        NTLMPercent       = round(toreal(NTLMLogons) / toreal(NTLMLogons + max_of(KerberosLogons,1)) * 100, 1),
        AuthProfile       = case(
            KerberosLogons == 0,               "NTLM-Only (no Kerberos ever observed)",
            NTLMLogons > KerberosLogons * 3,   "Predominantly NTLM (>75%)",
            NTLMLogons > KerberosLogons,        "Majority NTLM",
                                               "Mixed NTLM+Kerberos"
        )
    | where NTLMLogons > 5
    | extend
        DowngradeRisk = case(
            KerberosLogons == 0 and NTLMLogons > 20,
                "High — Pure NTLM account, no Kerberos baseline established",
            NTLMPackages has "NTLM V1",
                "High — NTLMv1 detected within NTLM traffic",
            NTLMPercent >= 80,
                "Medium — Predominantly NTLM, possible downgrade or legacy config",
            "Low — Occasional NTLM alongside Kerberos"
        );

// ──────────────────────────────────────────────────────────────
// PART 4 — Daily NTLMv1 Trend (for remediation tracking)
// ──────────────────────────────────────────────────────────────
let DailyTrend = NTLMv1Events
    | summarize
        NTLMv1Count     = count(),
        UniqueAccounts  = dcount(Account),
        UniqueHosts     = dcount(DestHost),
        LMCount         = countif(NTLMVersion == "LM"),
        NTLMv1Count_ESS = countif(NTLMVersion has "Client Challenge")
        by Day = bin(TimeGenerated, 1d)
    | order by Day desc;

// ──────────────────────────────────────────────────────────────
// PRIMARY OUTPUT — NTLMv1 accounts sorted by risk
// Comment/uncomment the sub-query at the bottom to switch views
// ──────────────────────────────────────────────────────────────
NTLMv1Summary
| project-reorder
    RiskLevel, Account,
    FirstSeen, LastSeen,
    TotalEvents, UniqueDestHosts, UniqueSourceIPs,
    DestHosts, SourceIPs, SourceHosts,
    NTLMVersions, LogonTypes, IsMachineAccount, RiskScore
| order by RiskScore desc, TotalEvents desc

// ── Alternate views (comment out primary output above and run one of these) ──
// --- NTLM-Only account profile ---
// AllNTLMAccounts
// | project-reorder
//     AccountKey, Domain, DowngradeRisk, AuthProfile,
//     NTLMLogons, KerberosLogons, NTLMPercent,
//     UniqueTargets, Targets, SourceIPs, NTLMPackages,
//     FirstSeen, LastSeen
// | order by NTLMLogons desc

// --- Daily trend for exec reporting ---
// DailyTrend

// ============================================================
// HUNT-30 | AD Hunting: RC4 and DES Kerberos Weak Encryption
// ============================================================
// Description:
//   Hunts for Kerberos tickets using weak or deprecated encryption algorithms.
//   Modern hardened domains should exclusively use AES-256 (0x12) or AES-128 (0x11).
//   Presence of RC4 or DES is either a misconfiguration, legacy client, or
//   an active attack leveraging downgrade to enable offline hash cracking.
//
//   Encryption type reference:
//     0x1  → DES-CBC-CRC        (prehistoric — should never appear)
//     0x3  → DES-CBC-MD5        (prehistoric — should never appear)
//     0x10 → Triple-DES 3DES    (deprecated)
//     0x17 → RC4-HMAC           (enabled by default; main Kerberoasting target)
//     0x18 → RC4-HMAC-EXP       (weak export RC4 variant)
//     0x11 → AES-128-CTS-HMAC-SHA1  (acceptable)
//     0x12 → AES-256-CTS-HMAC-SHA1  (recommended — gold standard)
//
//   Attack techniques enabled by weak Kerberos encryption:
//     - Kerberoasting:  Request TGS (4769) for SPN with RC4 → crack offline
//     - AS-REP Roasting: Request TGT (4768) with no pre-auth + RC4 → crack offline
//     - Golden Ticket:   krbtgt RC4 hash → forge TGTs for any account
//     - Silver Ticket:   Service RC4 hash → forge TGS without KDC involvement
//     - DES downgrade:   Active MITM forcing DES → trivially crackable
//
//   Key AD attribute to check on flagged accounts:
//     msDS-SupportedEncryptionTypes — bitmask controlling allowed enc types
//     Value 0 (or missing) = defaults to RC4 + DES → HIGH RISK
//
// Mitre ATT&CK:
//   - T1558.003: Steal or Forge Kerberos Tickets — Kerberoasting
//   - T1558.004: Steal or Forge Kerberos Tickets — AS-REP Roasting
//   - T1558.001: Steal or Forge Kerberos Tickets — Golden Ticket
//   - T1558.002: Steal or Forge Kerberos Tickets — Silver Ticket
//   - T1557:     Adversary-in-the-Middle (forced downgrade)
//
// Data Sources: SecurityEvent (EventID 4768, 4769, 4770, 4771)
// Query Period: 30 days
// Hunting Focus: RC4/DES ticket discovery, Kerberoastable accounts,
//               per-account encryption posture, daily weak-enc trend
// ============================================================

let LookbackPeriod = 30d;
let RC4EncTypes    = dynamic(["0x17", "0x18"]);
let DESEncTypes    = dynamic(["0x1", "0x3", "0x10"]);
let WeakEncTypes   = dynamic(["0x1", "0x3", "0x10", "0x17", "0x18"]);
let StrongEncTypes = dynamic(["0x11", "0x12"]);          // AES-128 and AES-256

// ──────────────────────────────────────────────────────────────
// PART 1 — All Kerberos events with encryption type annotation
// ──────────────────────────────────────────────────────────────
let KerberosTickets = SecurityEvent
    | where TimeGenerated >= ago(LookbackPeriod)
    | where EventID in (4768, 4769, 4770, 4771)
    | extend
        EncType     = tostring(column_ifexists("TicketEncryptionType", "")),
        PreAuth     = tostring(column_ifexists("PreAuthType", "")),
        ServiceName = tostring(extract(@"<Data Name='ServiceName'>([^<]+)</Data>", 1, EventData)),
        ClientAddr  = tostring(extract(@"<Data Name='IpAddress'>([^<]+)</Data>", 1, EventData)),
        FailCode    = tostring(extract(@"<Data Name='Status'>([^<]+)</Data>", 1, EventData))
    | where isnotempty(EncType) and EncType != "0"     // 0 = no encryption field logged
    | extend
        EncClass = case(
            EncType == "0x12", "AES256",
            EncType == "0x11", "AES128",
            EncType == "0x17", "RC4-HMAC",
            EncType == "0x18", "RC4-HMAC-EXP",
            EncType == "0x1",  "DES-CBC-CRC",
            EncType == "0x3",  "DES-CBC-MD5",
            EncType == "0x10", "3DES",
            strcat("Unknown-", EncType)),
        IsWeak     = EncType in (WeakEncTypes),
        IsRC4      = EncType in (RC4EncTypes),
        IsDES      = EncType in (DESEncTypes),
        EventDesc  = case(
            EventID == 4768, "TGT-Request",
            EventID == 4769, "TGS-Request",
            EventID == 4770, "TGT-Renewal",
            EventID == 4771, "PreAuth-Failure",
            "Unknown"),
        IsKerberoastTarget = (EventID == 4769
            and EncType in (RC4EncTypes)
            and ServiceName !endswith "$"
            and ServiceName !in ("krbtgt", "kadmin", "kadmin/changepw")),
        IsASREPTarget      = (EventID == 4768
            and EncType in (WeakEncTypes)
            and PreAuth == "0"),
        IsMachineAccount   = (TargetUserName endswith "$");

// ──────────────────────────────────────────────────────────────
// PART 2 — Kerberoastable Service Accounts (RC4 TGS requests)
//   Priority hunting target: each RC4 TGS represents an offline-crackable hash
// ──────────────────────────────────────────────────────────────
let KerberoastCandidates = KerberosTickets
    | where IsKerberoastTarget
    | summarize
        FirstSeen           = min(TimeGenerated),
        LastSeen            = max(TimeGenerated),
        RC4TGSCount         = count(),
        UniqueRequestors    = dcount(TargetUserName),
        Requestors          = make_set(TargetUserName, 10),
        SourceIPs           = make_set(ClientAddr, 10),
        EncTypes            = make_set(EncClass)
        by ServiceName, Computer
    | extend
        RiskLevel = case(
            RC4TGSCount >= 50,    "Critical — High-volume RC4 TGS (mass Kerberoasting)",
            RC4TGSCount >= 10,    "Critical — Repeated RC4 TGS requests for this SPN",
            UniqueRequestors >= 5,"High — Multiple accounts requesting RC4 tickets for this SPN",
            RC4TGSCount >= 3,     "High — Recurring RC4 TGS requests",
                                  "Medium — Single RC4 TGS (Kerberoastable SPN confirmed)"
        ),
        Recommendation = strcat(
            "1. Verify msDS-SupportedEncryptionTypes on service account for SPN '", ServiceName,
            "'; 2. Set to 0x18 (AES128+AES256) or 0x8 (AES256 only); ",
            "3. Rotate service account password immediately if RC4TGSCount > 1")
    | project-reorder
        FirstSeen, LastSeen, RiskLevel,
        ServiceName, Computer,
        RC4TGSCount, UniqueRequestors, Requestors,
        SourceIPs, EncTypes, Recommendation;

// ──────────────────────────────────────────────────────────────
// PART 3 — DES Kerberos Events (always critical — should be 0 in modern AD)
// ──────────────────────────────────────────────────────────────
let DESEvents = KerberosTickets
    | where IsDES
    | summarize
        FirstSeen       = min(TimeGenerated),
        LastSeen        = max(TimeGenerated),
        TotalDESTickets = count(),
        TGTRequests     = countif(EventID == 4768),
        TGSRequests     = countif(EventID == 4769),
        TGTRenewals     = countif(EventID == 4770),
        PreAuthFails    = countif(EventID == 4771),
        Services        = make_set(ServiceName, 15),
        SourceIPs       = make_set(ClientAddr, 10),
        EncTypes        = make_set(EncClass),
        HasCRCVariant   = max(toint(EncType == "0x1"))  // Absolute weakest
        by TargetUserName, TargetDomainName, Computer
    | extend
        RiskLevel = case(
            HasCRCVariant == 1,    "Critical — DES-CBC-CRC detected (weakest possible Kerberos)",
            TGSRequests >= 5,      "Critical — DES TGS requests (offline-crackable service tickets)",
            TotalDESTickets >= 10, "High    — High-volume DES Kerberos (possible DES-only account)",
                                   "High    — DES Kerberos ticket detected"
        ),
        InvestigationNote = strcat(
            "Run: Get-ADUser ", TargetUserName,
            " -Properties msDS-SupportedEncryptionTypes,UseDESKeyOnly | Select Name,msDS*,UseDES*  ",
            "— If UseDESKeyOnly=True, remove this attribute immediately. ",
            "Set msDS-SupportedEncryptionTypes = 24 (AES128+AES256)")
    | project-reorder
        FirstSeen, LastSeen, RiskLevel,
        TargetUserName, TargetDomainName, Computer,
        TotalDESTickets, TGTRequests, TGSRequests, TGTRenewals, PreAuthFails,
        Services, SourceIPs, EncTypes, HasCRCVariant, InvestigationNote;

// ──────────────────────────────────────────────────────────────
// PART 4 — Per-Account Encryption Posture (remediation priority list)
//   Shows every account's AES vs RC4 vs DES ticket ratio
//   Feed this into a remediation tracker
// ──────────────────────────────────────────────────────────────
let AccountEncPosture = KerberosTickets
    | where EventID in (4768, 4769)      // TGT and TGS only
    | summarize
        TotalTickets     = count(),
        AES256Tickets    = countif(EncType == "0x12"),
        AES128Tickets    = countif(EncType == "0x11"),
        RC4Tickets       = countif(IsRC4),
        DESTickets       = countif(IsDES),
        WeakTickets      = countif(IsWeak),
        UniqueServices   = dcount(ServiceName),
        Services         = make_set(ServiceName, 15),
        SourceIPs        = make_set(ClientAddr, 10),
        EncTypes         = make_set(EncClass),
        FirstSeen        = min(TimeGenerated),
        LastSeen         = max(TimeGenerated)
        by TargetUserName, TargetDomainName
    | where WeakTickets > 0
    | extend
        WeakPercent   = round(toreal(WeakTickets) / toreal(TotalTickets) * 100, 1)
    | extend
        EncProfile    = strcat(
            iff(AES256Tickets > 0, strcat("AES256:", tostring(AES256Tickets), " "), ""),
            iff(AES128Tickets > 0, strcat("AES128:", tostring(AES128Tickets), " "), ""),
            iff(RC4Tickets > 0,    strcat("RC4:",    tostring(RC4Tickets),    " "), ""),
            iff(DESTickets > 0,    strcat("DES:",    tostring(DESTickets),    " "), "")
        ),
        RemPriority   = case(
            DESTickets > 0 and RC4Tickets > 0,    "P1 — DES + RC4 both active",
            DESTickets > 0,                        "P1 — DES encryption in active use",
            WeakPercent == 100.0,                  "P2 — 100% RC4, no AES at all",
            WeakPercent >= 75,                     "P2 — Predominantly RC4 (>75% of tickets)",
            WeakPercent >= 50,                     "P2 — Majority RC4",
            AES256Tickets == 0 and AES128Tickets == 0,
                                                   "P2 — No AES tickets observed",
                                                   "P3 — Mixed AES+RC4, investigate client"
        )
    | project-reorder
        TargetUserName, TargetDomainName, RemPriority, WeakPercent, EncProfile,
        TotalTickets, AES256Tickets, AES128Tickets, RC4Tickets, DESTickets,
        UniqueServices, Services, SourceIPs, FirstSeen, LastSeen
    | order by RemPriority asc, WeakPercent desc;

// ──────────────────────────────────────────────────────────────
// PART 5 — Daily Weak Encryption Trend (remediation progress tracking)
// ──────────────────────────────────────────────────────────────
let DailyWeakEncTrend = KerberosTickets
    | where IsWeak
    | summarize
        WeakTickets     = count(),
        RC4Count        = countif(IsRC4),
        DESCount        = countif(IsDES),
        UniqueAccounts  = dcount(TargetUserName),
        UniqueServices  = dcount(ServiceName)
        by Day = bin(TimeGenerated, 1d), EncClass
    | order by Day desc, EncClass asc;

// ──────────────────────────────────────────────────────────────
// PRIMARY OUTPUT — Kerberoastable SPNs (most actionable signal)
// Comment out and uncomment alternate views below as needed
// ──────────────────────────────────────────────────────────────
KerberoastCandidates
| order by RiskLevel asc, RC4TGSCount desc

